WFJ.Data.add("quest", {
  [87288] = { "柔らかなSaberの毛皮", "Soft Nightsaber Peltを$N1枚、Aldriaのところへ持って行ってください。", "こんにちは、旅の方！ 私たちの村を楽しんでいただけているといいのですが。私はDolanaarが好きなんです。小さくて素朴で、みんな親切ですから。\n\n私は地元の商人で、旅に役立ちそうな道具や小物をいろいろ仕入れています。実は、取引に興味がおありなら、nightsaber peltsが少し必要なんです。この雄大な生き物たちは美しいのですが、このあたりのものはかなり気が荒いので、身を守るために戦っても気に病むことはありませんよ。", "また会えて嬉しいよ！取引しに来たのかい？", "まあ、素晴らしいですね。これほど雄大な動物たちに暴力を振るうのは残念なことですが、道の安全を守るのは大切なことですし、この毛皮は美しい毛布やショールになるでしょう。\n\nさあ、彼らを忘れないよう、これを差し上げます。柔らかくて丈夫な品ですよ。", 0x8e68b306, 0x5828382e, 0x9dca9c14, 0x16c13c9e, 0x8c6d1a47, "....." },
  [87295] = { "反射する表面", "Redstone Basilisk Scaleを$N1枚、Bernie Heistenのところへ持って行ってください。", "Nethergarde Keepへ来る途中、外の荒野をうろつくRedstoneのバジリスクを見かけたかもしれないな。あいつらはタフな生き物で、Blasted Landsで生き抜けるよう見事に適応している。中でも重要な特性のひとつが頑丈な鱗だ。熱を跳ね返し、砂や風から身を守り、武器の一撃さえもそらすんだ！\n\n盾を作るのに完璧な素材でな、一束持ってきてくれたら、たっぷり礼をするよ。ただし、状態のいいものだけを持ってきてくれ！", nil, nil, 0x92d88808, 0xe22bd6d3, 0xa15486f2, nil, nil, "...mm" },
  [87318] = { "失われし者たちの心", "Cormaの相棒Esseneを探す。", "Thandol Spanは、Dark Ironsが橋を爆破して以来ずっと危険な場所だったけど、まさかそこで奴らに出くわすとは思わなかった！\n\nなんとか逃げ出せたけど、相棒のEsseneを見失ってしまった。あちこち探し回ったのに、手がかりひとつ見つからない。Dark Ironsに捕まったのか？下の川に落ちたのか？向こう岸まで戻れたのか？分からない！生きているかどうかさえ分からないんだ！\n\nお願いだ、彼女の手がかりを見かけたら知らせてくれ！", nil, nil, 0xecc2e5e4, 0xdc3f5e49, 0xbcc51c2c, nil, nil, "...mm" },
  [87346] = { "Chieftain Bloodmaw", "Chieftain Bloodmawを倒し、彼のメイスをTimbermaw HoldにいるGorn One Eyeのところへ持って行ってください。", "LegashiがBlackmawを蹂躙したとき、ほかのTimbermawはsatyrを締め出すため、砦への通路を封鎖した。彼らが難民として生き延びていたとは、思いもしなかった。\n\n同胞を助けたいのはやまやまだが、我々も自分たちの戦いを抱えている。LegashiがBlackmawを脅かしているように、Deadwoodも我々を脅かしているのだ。割けるウォリアーは多くない。\n\nDeadwoodの族長、Bloodmawはここから南のFelpaw Villageにいる。奴を始末すれば、我々の戦いはずっと楽になる。奴の鎚矛を持ってくれば、我々の援助を約束しよう。", nil, nil, 0x3b744944, 0x2700ce9e, 0x4b1607a6, nil, nil, "...mm" },
  [87451] = { "Rockardの思い出", "Carved Stone TrinketをSwamp of SorrowsのStonardにいるDispatch Commander Ruagのところへ持って行ってください。", "ogreが持っていたこの装身具は、オークの家族を描いた小さな石の彫刻のようだ。ここがRockardの町で、ogreが侵略してくる前にここに住んでいたオークたちの形見かもしれない。\n\nおそらくStonardの生存者たちにとって、思い出深い、あるいは霊的な価値があるものだろう。", nil, nil, 0xe8303448, 0xa4d0704b, 0xa59cb946, nil, nil, "...mm" },
  [87491] = { "自由の火花", "捕らわれた火の精霊を護衛してDun Modrの外へ連れ出し、自由にする。", "シュー！汚らわしいDark Ironsが我を召喚し、奴らのちっぽけな焚き火の脇に閉じ込めたのだ！\n\n炎は荒々しく、自由に燃え広がらねばならぬ！我を解き放て！逃げねば！燃やさねば！\n\nDark Ironは一人として無事では済まぬ！奴らを焼き尽くせ！奴らの黒色火薬を燃やせ！奴らの砦を、導火線を、愚かさを燃やせ！\n\n我を出せば、奴らを皆、燃やし尽くしてくれる！", nil, "なかなかの花火ショーだったな！あんなのは見たことがないと思うぜ！\n\n火のエレメンタルが、その、言ってみれば息切れしてくれて助かったよ。あのDark Ironどもじゃなく俺たちの方を狙うことにしてたら、まずいことになってたかもな！", 0x2b274e59, 0x187207a1, 0xa71d7ba7, nil, 0x70543ec1, "...m." },
  [87492] = { "不思議な水晶", "Damaged Blue Crystalを$N1個、Torwa Pathfinderのところへ持って帰ってください。", "このクレーターに点在する奇妙な水晶の塊を見かけたかもしれないね。私は鉱夫じゃないけど、この塊はこのあたりの土壌の堆積物とは合わないように思えるんだ。\n\n食料を探していたとき、ここからそう遠くないところで傷ついた水晶を見かけた気がする。この奇妙な結晶群の起源について、何か秘密を秘めているんじゃないかな？もし見つけたら、ぜひそのかけらを調べてみたいんだ。", nil, nil, 0xd3573c62, 0xf4ff9a47, 0x6335d894, nil, nil, "...mm" },
  [87494] = { "微結晶による汚染", "Crystal Infused ScaleをTorwa Pathfinderのところへ持って行ってください。", "この鱗はほかの鱗よりもわずかに光をよく反射し、虹色に輝いている。まるで小さな水晶の粒子が埋め込まれているかのようだ。\n\nTorwa Pathfinderなら、これで何か作れるかもしれない。", nil, nil, 0x036e64eb, 0x9b02bdb0, 0x0a7ad49b, nil, nil, "...mm" },
  [87760] = { "聖なる潜り手", "Stormscale Beastmistressを見つけて倒し、彼女のRod of Deep Dominionを持ち帰ってください。", "Darnassusから返事が届いた、{name}！\n\n動物のサンプルから、nagaがこの海の生き物たちを支配し、嫌がる乗騎や荷役の獣として使っていたことが分かった。あまりに強情なもの、年老いたもの、ひどく傷ついたものは、娯楽のために追い払っていたのだ。なんと非道な！\n\nこれを止めるのは我々の神聖な務めだ！\n\nnagaはRuins of Mathystraに兵を置いていて、沖からthreshersを捕らえているに違いない。奴らの獣使いを見つけて倒し、その支配の道具を持ち帰ってくれ！", "ついにこの謎が解き明かされ、動物たちもようやく安らぎを得られるのです！", "長い旅でしたね、{name}。でも、その甲斐はありました。\n\nついに、nagaが海の生き物たちを従わせるのに使っていた杖を奪い取ってくれたのですね。必ず破壊させます。これでthresherやウミガメたちも、ようやく安心して暮らせるでしょう。\n\nもう一度お礼を言います。あなたの粘り強さがついに報われました。私個人としても、あなたに感謝しています。", 0xbe769717, 0x6347b42a, 0xeef193cf, 0x983fbc72, 0x1f84dd59, "....." },
